// Uses resource hierarchy (mutex priority 1, buffer priority 2) to
// guarantee deadlock freedom. Both produce and consume acquire mutex
// before buffer, preventing circular wait.

// Produce: add item to buffer (mutex must be free)
atom produce(buf_len: i64, buf_cap: i64, mutex_held: i64)
requires: buf_len >= 0 && buf_cap > 0 && buf_len < buf_cap && mutex_held == 0;
ensures: result == buf_len + 1 && result <= buf_cap && result >= 0;
body: {
    buf_len + 1
};

// Consume: remove item from buffer (mutex must be free)
atom consume(buf_len: i64, buf_cap: i64, mutex_held: i64)
requires: buf_len > 0 && buf_cap > 0 && buf_len <= buf_cap && mutex_held == 0;
ensures: result == buf_len - 1 && result >= 0 && result < buf_cap;
body: {
    buf_len - 1
};

// Buffer available: check if space exists for production
atom buffer_available(buf_len: i64, buf_cap: i64)
requires: buf_len >= 0 && buf_cap > 0 && buf_len <= buf_cap;
ensures: result >= 0 && result <= 1 && (buf_len < buf_cap => result == 1) && (buf_len == buf_cap => result == 0);
body: {
    if buf_len < buf_cap { 1 } else { 0 }
};

// Buffer has items: check if items exist for consumption
atom buffer_has_items(buf_len: i64)
requires: buf_len >= 0;
ensures: result >= 0 && result <= 1 && (buf_len > 0 => result == 1) && (buf_len == 0 => result == 0);
body: {
    if buf_len > 0 { 1 } else { 0 }
};
